		this.skip_btn = this.controller.skip_btn;
		this.ff_btn = this.controller.ff_btn;
		this.pause_btn = this.controller.pause_btn;
		this.play_btn = this.controller.play_btn;
		this.replay_btn = this.controller.replay_btn;
		var root = this;
		
		function SetStartPosition(){
			root.play_btn.visible = false;
		    root.pause_btn.visible = true;
			root.ff_btn.visible = true;
			root.replay_btn.visible = false;
		}
		
		root.pause_btn.addEventListener("click", PauseAnimation);
		
		function PauseAnimation (event) { 
			root.paused = true;
			root.pause_btn.visible = false;
			root.play_btn.visible = true;
		}
		
		root.play_btn.addEventListener("click", PlayAnimation);
		
		function PlayAnimation (event) { 
			root.paused = false;
			SetStartPosition();
		}
		
		
		root.ff_btn.addEventListener("click", FFAnimation);
		root.ff_btn.addEventListener("dblclick", JumptoEnd)
		
		function FFAnimation(event){
			var headerposition = root.currentFrame + 72;
			if (headerposition > 380){
				root.gotoAndPlay(455);		
			}else{
				root.gotoAndPlay(headerposition);
			}
				
			PlayAnimation();
		}
		
		
		root.skip_btn.addEventListener("dblclick", JumptoEnd);
		
		function JumptoEnd(event){
			root.gotoAndPlay(455);
		}
